import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { CloakedCategory, CloakedGit, CloakedLimit, CloakedUsage } from '../types'
import {
  C,
  PULSE,
  ageColor,
  basename,
  cacheBar,
  categoryColor,
  categoryLabel,
  clockText,
  compact,
  contextBar,
  duration,
  parseTz,
  parseWeather,
  prettyModel,
  shortPlace,
  splitBar,
  tierColor,
  tooling,
} from './format'
import type { Seg } from './format'

const now = atom({ plugin: 'cloaked-statusline', key: 'now' } as const, 0)
const env = atom({ plugin: 'cloaked-statusline', key: 'env' } as const, null)
const usage = atom({ plugin: 'cloaked-statusline', key: 'usage' } as const, null)
const git = atom({ plugin: 'cloaked-statusline', key: 'git' } as const, null)
const weather = atom({ plugin: 'cloaked-statusline', key: 'weather' } as const, null)
const lastResponseAt = atom({ plugin: 'cloaked-statusline', key: 'lastResponseAt' } as const, null)
const isHidden = atom({ plugin: 'cloaked-statusline', key: 'isHidden' } as const, false)

const LABEL = 8
const EDITS = new Set(['Bash', 'Edit', 'MultiEdit', 'Write', 'NotebookEdit'])

type Config = { brand: string; location: string; units: 'u' | 'm'; ttlMs: number }

let config: Config = { brand: 'cloaked.agency', location: '', units: 'u', ttlMs: 5 * 60_000 }
let isRunning = false
let isUsageBusy = false
let isGitBusy = false
let gitSoon: { cancel: () => void } | undefined

function quiet($: EngineInterface, what: string, work: Promise<unknown>): void {
  work.catch((error: unknown) => $.ui.log(`${what}: ${String(error)}`, { to: 'debug' }))
}

async function refreshTime($: EngineInterface): Promise<void> {
  const t = await $.clock.now()
  await update($, now, () => t)
}

async function refreshEnv($: EngineInterface): Promise<void> {
  const [version, model, measured] = await Promise.all([
    $.session.version(),
    $.session.model(),
    $.session.usage(),
  ])
  let tz = { offsetMin: 0, name: 'UTC' }
  try {
    const out = await $.process.run(['date', '+%z %Z'], { timeoutMs: 3000 })
    tz = parseTz(out.stdout) ?? tz
  } catch {
    // No `date` here (Windows): the clock reads UTC.
  }
  const value = {
    version: version.base ?? version.version,
    model: prettyModel(model, measured.context.window),
    tzOffsetMin: tz.offsetMin,
    tzName: tz.name,
  }
  await update($, env, () => value)
}

async function refreshUsage($: EngineInterface): Promise<void> {
  if (isUsageBusy) return
  isUsageBusy = true
  try {
    const u = await $.session.usage({ breakdown: 'summary' })
    const b = u.context.breakdown
    const used: CloakedCategory[] = []
    let bufferTokens = 0
    for (const cat of b?.categories ?? []) {
      if (cat.kind === 'buffer') bufferTokens += cat.tokens
      if (cat.kind !== 'used') continue
      const label = categoryLabel(cat.name)
      const same = used.find(c => c.label === label)
      if (same) same.tokens += cat.tokens
      else used.push({ label, tokens: cat.tokens })
    }
    const limit = (kind: string): CloakedLimit | null => {
      const found = u.rateLimits.find(r => r.kind === kind)
      if (found === undefined) return null
      return found.resetsAt === undefined
        ? { percent: found.percentUsed }
        : { percent: found.percentUsed, resetsAt: found.resetsAt }
    }
    const value: CloakedUsage = {
      startedAt: u.startedAt,
      percent: b?.percentage ?? u.context.percent ?? null,
      maxTokens: b?.rawMaxTokens ?? u.context.window,
      used,
      bufferTokens,
      costUsd: u.cost?.usd ?? null,
      session: limit('five_hour'),
      weekly: limit('seven_day'),
    }
    await update($, usage, () => value)
  } finally {
    isUsageBusy = false
  }
}

async function runGit($: EngineInterface, args: string[]) {
  return $.process.run(['git', ...args], { timeoutMs: 5000 })
}

async function refreshGit($: EngineInterface): Promise<void> {
  if (isGitBusy) return
  isGitBusy = true
  try {
    const dir = await $.session.cwd()
    const inside = await runGit($, ['rev-parse', '--is-inside-work-tree'])
    if (inside.exitCode !== 0) {
      await update($, git, () => ({ dir, branch: null, lastCommitAt: null, modified: 0 }))
      return
    }
    const [symbolic, status, log] = await Promise.all([
      runGit($, ['symbolic-ref', '--short', '-q', 'HEAD']),
      runGit($, ['status', '--porcelain']),
      runGit($, ['log', '-1', '--format=%ct']),
    ])
    let branch = symbolic.stdout.trim()
    if (symbolic.exitCode !== 0 || branch === '') {
      branch = (await runGit($, ['rev-parse', '--short', 'HEAD'])).stdout.trim() || 'detached'
    }
    const seconds = Number(log.stdout.trim())
    const value: CloakedGit = {
      dir,
      branch,
      lastCommitAt: log.exitCode === 0 && seconds > 0 ? seconds * 1000 : null,
      modified: status.stdout.split('\n').filter(line => line.trim() !== '').length,
    }
    await update($, git, () => value)
  } finally {
    isGitBusy = false
  }
}

async function refreshWeather($: EngineInterface): Promise<void> {
  const where = config.location === '' ? '' : encodeURIComponent(config.location)
  const reply = await $.http.fetch(`https://wttr.in/${where}?${config.units}&format=%25t%7C%25C%7C%25l`, {
    headers: { 'User-Agent': 'curl/8.4.0' },
  })
  const parsed = reply.ok ? parseWeather(reply.text) : null
  if (parsed === null) return
  const value = {
    place: config.location === '' ? shortPlace(parsed.place) : config.location,
    temp: parsed.temp,
    condition: parsed.condition,
  }
  await update($, weather, () => value)
}

function refreshAll($: EngineInterface): Promise<unknown> {
  return Promise.allSettled([
    refreshTime($),
    refreshEnv($),
    refreshUsage($),
    refreshGit($),
    refreshWeather($),
  ])
}

function start($: EngineInterface): void {
  if (isRunning) return
  isRunning = true
  quiet($, 'refresh', refreshAll($))
  $.clock.every(1000, () => quiet($, 'clock', refreshTime($)))
  $.clock.every(15_000, () => quiet($, 'git', refreshGit($)))
  $.clock.every(20 * 60_000, () => quiet($, 'weather', refreshWeather($)))
  $.clock.every(30 * 60_000, () => quiet($, 'env', refreshEnv($)))
}

function refreshGitSoon($: EngineInterface): void {
  gitSoon?.cancel()
  gitSoon = $.clock.after(1200, () => quiet($, 'git', refreshGit($)))
}

async function markResponse($: EngineInterface): Promise<void> {
  const t = await $.clock.now()
  await update($, lastResponseAt, () => t)
}

export const register: Register = (on, options) => {
  isRunning = false
  isUsageBusy = false
  isGitBusy = false
  config = {
    brand: String(options.brand ?? '').trim() || 'cloaked.agency',
    location: String(options.location ?? '').trim(),
    units: options.units === 'metric' ? 'm' : 'u',
    ttlMs: Math.max(1, Number(options.cacheTtlMinutes ?? 5) || 5) * 60_000,
  }
  const { brand, location, ttlMs } = config

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    if (e.isInteractive || e.surface !== null) start($)
    await $.command.register({
      name: 'cloaked',
      description: 'cloaked.agency status band: toggle it, or pass hide, show or refresh',
      argumentHint: '[hide|show|refresh]',
    })
    return started
  })

  on('session.attach', ($, e, next) => {
    start($)
    return next(e)
  })

  on('session.measure', ($, e, next) => {
    if (e.changed.includes('context')) quiet($, 'cache', markResponse($))
    quiet($, 'usage', refreshUsage($))
    return next(e)
  })

  on('turn.complete', ($, e, next) => {
    if (e.agentId === undefined) {
      quiet($, 'cache', markResponse($))
      quiet($, 'env', refreshEnv($))
    }
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const ran = await next(e)
    if (isRunning && EDITS.has(String(e.tool))) refreshGitSoon($)
    return ran
  }).catch(($, e, next) => next(e))

  on('command.run', { command: 'cloaked' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'refresh') {
      start($)
      await refreshAll($)
      return { text: 'cloaked.agency status band refreshed.' }
    }
    const hide = arg === 'hide' ? true : arg === 'show' ? false : !(await read($, isHidden))
    await update($, isHidden, () => hide)
    return { text: hide ? 'Status band hidden. /cloaked show brings it back.' : 'Status band shown.' }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isHidden))) return next(e)

    const [t, en, us, gi, we, last] = await Promise.all([
      read($, now),
      read($, env),
      read($, usage),
      read($, git),
      read($, weather),
      read($, lastResponseAt),
    ])
    const { Box, Text } = $.ui.resolve(e)
    const width = Math.max(24, e.props.bodyColumns)
    const rows = e.props.maxRows

    const paint = (segs: Seg[]) => segs.map(s => <Text color={s.color} bold={s.bold}>{s.text}</Text>)
    const label = (text: string) => <Text color={C.label}>{text}</Text>
    const sep = () => <Text color={C.sep}> │ </Text>
    const pad = (text: string) => text.padEnd(LABEL)

    // Header: the brand, and a rule that pulses once a second.
    const dot = brand.indexOf('.')
    const head = dot > 0 ? brand.slice(0, dot) : brand
    const tail = dot > 0 ? brand.slice(dot) : ''
    const pulse = PULSE[Math.floor(t / 1000) % PULSE.length] ?? PULSE[0]
    const header = (
      <Box>
        <Text color={pulse}>── </Text>
        <Text color={C.blue} bold>┃</Text>
        <Text color={C.orange} bold>┃ </Text>
        <Text color={C.blue} bold>{head}</Text>
        <Text color={C.orange} bold>{tail}</Text>
        <Text color={pulse}> {'─'.repeat(Math.max(0, width - brand.length - 7))}</Text>
      </Box>
    )

    // LOC: place, local time, weather.
    const clock = en === null ? '--:--' : `${clockText(t, en.tzOffsetMin)} ${en.tzName}`.trim()
    const loc = (
      <Box>
        {label('LOC ')}
        <Text>{we?.place || location || '--'}</Text>
        {sep()}
        <Text color={C.blue}>{clock}</Text>
        {sep()}
        <Text>{we === null ? '--' : `${we.temp} ${we.condition}`}</Text>
      </Box>
    )

    // ENV: version, model, cost, session length.
    const envRow = (
      <Box>
        {label('ENV ')}
        <Text>CC {en?.version ?? '--'}</Text>
        {sep()}
        <Text color={C.blue} bold>{en?.model ?? '--'}</Text>
        {sep()}
        <Text color={C.cost}>{us?.costUsd == null ? '$--' : `$${us.costUsd.toFixed(2)}`}</Text>
        {sep()}
        <Text color={C.blue}>{us === null ? '--' : duration(t - us.startedAt)}</Text>
      </Box>
    )

    // CONTEXT: the window by category.
    const ctxPct = us?.percent == null ? '--%' : `${Math.round(us.percent)}%`
    const ctxRight = ` ${ctxPct.padStart(4)}`
    const context = (
      <Box>
        {label(pad('CONTEXT'))}
        {paint(contextBar(us, width - LABEL - ctxRight.length))}
        <Text color={C.blue} bold>{ctxRight}</Text>
      </Box>
    )

    // The categories beneath it.
    const used = us?.used ?? []
    const tool = tooling(used)
    const toolPct = us === null || us.maxTokens <= 0 ? 0 : Math.round((tool / us.maxTokens) * 100)
    const detail = (
      <Box paddingLeft={LABEL} flexWrap="wrap" columnGap={2}>
        <Box>
          {label('tooling ')}
          <Text color={C.blue} bold>{compact(tool)}</Text>
          <Text color={C.label}> · </Text>
          <Text color={C.blue}>{toolPct}%</Text>
          <Text color={C.sep}> │</Text>
        </Box>
        {used.map(cat => (
          <Box>
            <Text color={categoryColor(cat.label)}>━ </Text>
            {label(`${cat.label} `)}
            <Text>{compact(cat.tokens)}</Text>
          </Box>
        ))}
      </Box>
    )

    // SESSION and WEEKLY: one bar filling from the centre out.
    const sPct = us?.session?.percent ?? null
    const wPct = us?.weekly?.percent ?? null
    const sText = sPct === null ? '--%' : `${Math.round(sPct)}%`
    const wText = wPct === null ? '--%' : `${Math.round(wPct)}%`
    const sessionLeft = `${sText.padEnd(4)} `
    const sessionRight = ` ${wText.padStart(4)} `
    const sessionBar = width - LABEL - sessionLeft.length - sessionRight.length - 'WEEKLY'.length
    const session = (
      <Box>
        {label(pad('SESSION'))}
        <Text color={sPct === null ? C.label : tierColor(sPct, C.green)} bold>{sessionLeft}</Text>
        {paint(splitBar(sPct, wPct, sessionBar))}
        <Text color={wPct === null ? C.label : tierColor(wPct, C.weekly)} bold>{sessionRight}</Text>
        {label('WEEKLY')}
      </Box>
    )

    // CACHE: drains over its TTL after the last response.
    const cacheRight = 11
    const cache = cacheBar(last, t, ttlMs, e.props.isWorking, width - LABEL - cacheRight)
    const cacheRow = (
      <Box>
        {label(pad('CACHE'))}
        {paint(cache.bar)}
        <Text color={cache.color} bold>{` ${cache.label}`.padStart(cacheRight)}</Text>
      </Box>
    )

    // Footer: folder, branch, last commit age, changed files.
    const age = gi?.lastCommitAt == null ? null : t - gi.lastCommitAt
    const footer = (
      <Box>
        <Text color={C.blue}>◆ </Text>
        {label('PWD ')}
        <Text bold>{gi === null ? '--' : basename(gi.dir)}</Text>
        {sep()}
        <Text color={C.blue}>⎇ {gi?.branch ?? 'no git'}</Text>
        {sep()}
        {label('Age ')}
        <Text color={age === null ? C.label : ageColor(age)}>{age === null ? '--' : duration(age)}</Text>
        {sep()}
        {label('Mod ')}
        <Text>{gi?.modified ?? 0}</Text>
      </Box>
    )

    // Fewer rows to spare: drop the detail first, then the header and LOC.
    const isRoomy = rows >= 9
    const isTight = rows < 7

    return (
      <Box flexDirection="column" width={width}>
        {!isTight && header}
        {!isTight && loc}
        {envRow}
        {context}
        {isRoomy && detail}
        {session}
        {cacheRow}
        {footer}
      </Box>
    )
  })
}

