import type { CloakedCategory, CloakedUsage } from '../types'

export const C = {
  blue: '#4fa3d1',
  orange: '#f0743c',
  label: '#8b949e',
  sep: '#484f58',
  track: '#30363d',
  buffer: '#5a636e',
  cost: '#e3a84b',
  green: '#3fb68b',
  yellow: '#e6c34a',
  red: '#f0563c',
  weekly: '#5aa9d6',
} as const

const CATEGORY_COLORS: Record<string, string> = {
  system: '#9aa4b2',
  tools: '#d0d7de',
  mcp: '#3fa7c9',
  'mcp-instr': '#3fb68b',
  agents: '#8fb8e8',
  memory: '#f07b52',
  skills: '#e6c34a',
  cmds: '#7ee0c3',
  msgs: '#b48ae0',
}

export const PULSE = ['#2f3542', '#46505f', '#5e6b7d', '#46505f'] as const

/** One run of same-styled cells in a bar or a row. */
export type Seg = { text: string; color?: string; bold?: boolean }

export function categoryLabel(name: string): string {
  const n = name.toLowerCase()
  if (n.includes('mcp') && n.includes('instr')) return 'mcp-instr'
  if (n.includes('mcp')) return 'mcp'
  if (n.includes('system prompt')) return 'system'
  if (n.includes('tool')) return 'tools'
  if (n.includes('agent')) return 'agents'
  if (n.includes('memory')) return 'memory'
  if (n.includes('skill')) return 'skills'
  if (n.includes('slash') || n.includes('command')) return 'cmds'
  if (n.includes('message')) return 'msgs'
  return n.split(/\s+/)[0] ?? n
}

export function categoryColor(label: string): string {
  return CATEGORY_COLORS[label] ?? '#9aa4b2'
}

function oneDecimal(x: number): string {
  return String(Math.round(x * 10) / 10)
}

/** 2400 is 2.4k, 15000 is 15k, 338000 is 338k, 1200000 is 1.2M. */
export function compact(n: number): string {
  if (n >= 1_000_000) return `${oneDecimal(n / 1_000_000)}M`
  if (n >= 1_000) {
    const k = n / 1_000
    return `${k >= 10 ? Math.round(k) : oneDecimal(k)}k`
  }
  return String(Math.round(n))
}

/** 45s, 56m, 2h 05m, 3d 4h. */
export function duration(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  if (m < 60) return `${m}m`
  const h = Math.floor(m / 60)
  if (h < 24) return `${h}h ${String(m % 60).padStart(2, '0')}m`
  return `${Math.floor(h / 24)}d ${h % 24}h`
}

/** m:ss, for the cache countdown. */
export function countdown(ms: number): string {
  const s = Math.max(0, Math.ceil(ms / 1000))
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}

/** Wall clock HH:MM at a UTC offset, from epoch milliseconds. */
export function clockText(now: number, offsetMin: number): string {
  const total = Math.floor(now / 60_000) + offsetMin
  const m = ((total % 1440) + 1440) % 1440
  return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`
}

/** Parses `date +'%z %Z'` output ("-0700 MST"). */
export function parseTz(text: string): { offsetMin: number; name: string } | null {
  const m = /([+-])(\d{2})(\d{2})\s*(\S*)/.exec(text.trim())
  if (!m) return null
  const sign = m[1] === '-' ? -1 : 1
  return { offsetMin: sign * (Number(m[2]) * 60 + Number(m[3])), name: m[4] ?? '' }
}

function capitalize(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase()
}

/** "claude-opus-5-5[1m]" or "Opus 5.5 (1M context)" both read "Opus 5.5 (1M)". */
export function prettyModel(raw: string, window: number): string {
  let s = raw.trim()
  const id = /claude-(opus|sonnet|haiku|fable)-(\d+)(?:-(\d{1,2})(?!\d))?(?:-\d{8})?(\[1m\])?/i.exec(s)
  if (id) {
    s = `${capitalize(id[1] ?? '')} ${id[2]}${id[3] ? `.${id[3]}` : ''}${id[4] ? ' (1M)' : ''}`
  } else {
    s = s
      .replace(/^default\s*\((.*)\)$/i, '$1')
      .replace(/\s*context\s*\)/i, ')')
      .replace(/\s*\(\s*\)/, '')
  }
  if (window >= 1_000_000 && !/\(1M\)/i.test(s)) s += ' (1M)'
  return s
}

const US_STATES: Record<string, string> = {
  alabama: 'AL', alaska: 'AK', arizona: 'AZ', arkansas: 'AR', california: 'CA',
  colorado: 'CO', connecticut: 'CT', delaware: 'DE', florida: 'FL', georgia: 'GA',
  hawaii: 'HI', idaho: 'ID', illinois: 'IL', indiana: 'IN', iowa: 'IA', kansas: 'KS',
  kentucky: 'KY', louisiana: 'LA', maine: 'ME', maryland: 'MD', massachusetts: 'MA',
  michigan: 'MI', minnesota: 'MN', mississippi: 'MS', missouri: 'MO', montana: 'MT',
  nebraska: 'NE', nevada: 'NV', 'new hampshire': 'NH', 'new jersey': 'NJ',
  'new mexico': 'NM', 'new york': 'NY', 'north carolina': 'NC', 'north dakota': 'ND',
  ohio: 'OH', oklahoma: 'OK', oregon: 'OR', pennsylvania: 'PA', 'rhode island': 'RI',
  'south carolina': 'SC', 'south dakota': 'SD', tennessee: 'TN', texas: 'TX', utah: 'UT',
  vermont: 'VT', virginia: 'VA', washington: 'WA', 'west virginia': 'WV',
  wisconsin: 'WI', wyoming: 'WY', 'district of columbia': 'DC',
}

/** "Glendale, Arizona, United States" reads "Glendale, AZ". */
export function shortPlace(raw: string): string {
  const parts = raw.split(',').map(p => p.trim()).filter(Boolean)
  if (parts.length === 0) return ''
  const city = parts[0]!
  const region = parts[1]
  if (region === undefined) return capitalize(city)
  const state = US_STATES[region.toLowerCase()]
  return `${city}, ${state ?? region}`
}

/** Parses wttr.in's `format=%t|%C|%l` reply. */
export function parseWeather(text: string): { temp: string; condition: string; place: string } | null {
  const [temp, condition, place] = text.trim().split('|')
  if (temp === undefined || condition === undefined || !/°/.test(temp)) return null
  return { temp: temp.replace(/^\+/, '').trim(), condition: condition.trim(), place: (place ?? '').trim() }
}

/** Merges runs of the same color so a bar is a handful of Text elements. */
function merge(cells: Seg[]): Seg[] {
  const out: Seg[] = []
  for (const cell of cells) {
    const last = out.at(-1)
    if (last !== undefined && last.color === cell.color && last.bold === cell.bold) last.text += cell.text
    else out.push({ ...cell })
  }
  return out
}

function repeat(char: string, n: number, color: string): Seg[] {
  return n > 0 ? [{ text: char.repeat(n), color }] : []
}

/**
 * The context window as one bar: each category its own color, the free
 * window as a dim track, the autocompact buffer dashed at the end.
 */
export function contextBar(usage: CloakedUsage | null, width: number): Seg[] {
  if (width <= 0) return []
  if (usage === null) return repeat('─', width, C.track)
  const total = usage.maxTokens
  if (total <= 0 || usage.used.length === 0) {
    const filled = Math.round(((usage.percent ?? 0) / 100) * width)
    return merge([...repeat('━', Math.min(width, filled), C.blue), ...repeat('─', width - filled, C.track)])
  }
  const bufferCells = Math.min(width, Math.round((usage.bufferTokens / total) * width))
  let room = width - bufferCells
  const cells: Seg[] = []
  for (const cat of usage.used) {
    if (room <= 0) break
    const n = Math.min(room, Math.max(cat.tokens > 0 ? 1 : 0, Math.round((cat.tokens / total) * width)))
    cells.push(...repeat('━', n, categoryColor(cat.label)))
    room -= n
  }
  cells.push(...repeat('─', room, C.track))
  cells.push(...repeat('╌', bufferCells, C.buffer))
  return merge(cells)
}

/** Teal or blue to half, orange to 80, red past it. */
export function tierColor(percent: number, base: string): string {
  if (percent >= 80) return C.red
  if (percent >= 50) return C.orange
  return base
}

function half(percent: number | null, cells: number, base: string): Seg[] {
  const filled = percent === null ? 0 : Math.min(cells, Math.round((percent / 100) * cells))
  const out: Seg[] = []
  for (let i = 0; i < filled; i++) out.push({ text: '━', color: tierColor(((i + 1) / cells) * 100, base) })
  return out
}

/**
 * Session (five hour) and weekly limits on one bar that fills from the centre
 * out: the session to the left, the week to the right, a diamond between.
 */
export function splitBar(session: number | null, weekly: number | null, width: number): Seg[] {
  const inner = Math.max(0, width - 1)
  const leftCells = Math.floor(inner / 2)
  const rightCells = inner - leftCells
  const left = half(session, leftCells, C.green).reverse()
  const right = half(weekly, rightCells, C.weekly)
  return merge([
    ...repeat(' ', leftCells - left.length, C.track),
    ...left,
    { text: '◆', color: C.orange },
    ...right,
    ...repeat(' ', rightCells - right.length, C.track),
  ])
}

export type CacheState = { bar: Seg[]; label: string; color: string }

/** The prompt cache: live while a turn runs, draining after, cold past its TTL. */
export function cacheBar(
  lastResponseAt: number | null,
  now: number,
  ttlMs: number,
  isWorking: boolean,
  width: number,
): CacheState {
  if (isWorking) return { bar: repeat('━', width, C.green), label: 'live', color: C.green }
  if (lastResponseAt === null) return { bar: repeat('─', width, C.track), label: 'idle', color: C.label }
  const left = ttlMs - (now - lastResponseAt)
  if (left <= 0) return { bar: repeat('─', width, C.red), label: 'cold', color: C.red }
  const frac = left / ttlMs
  const color = frac < 0.25 ? C.yellow : C.green
  const filled = Math.min(width, Math.ceil(frac * width))
  return {
    bar: merge([...repeat('━', filled, color), ...repeat('─', width - filled, C.track)]),
    label: `warm ${countdown(left)}`,
    color,
  }
}

/** Tokens spent on everything but the conversation itself. */
export function tooling(used: readonly CloakedCategory[]): number {
  return used.filter(c => c.label !== 'msgs').reduce((sum, c) => sum + c.tokens, 0)
}

export function ageColor(ms: number): string {
  if (ms < 3_600_000) return C.green
  if (ms < 86_400_000) return C.yellow
  return C.label
}

export function basename(path: string): string {
  const parts = path.split(/[\\/]/).filter(Boolean)
  return parts.at(-1) ?? path
}

